import Component from 'flarum/common/Component';
import Icon from 'flarum/common/components/Icon';
import humanTime from 'flarum/common/helpers/humanTime';
import classList from 'flarum/common/utils/classList';
import describeEvent from '../utils/describeEvent';
/**
 * A notice in a conversation's stream, such as a member leaving it: a line
 * saying what happened and when, laid out as a discussion's event posts are.
 */
export default class EventMessage extends Component {
  view() {
    const message = this.attrs.message;
    return m("div", {
      className: classList('EventMessage', `EventMessage--${message.type()}`)
    }, m(Icon, {
      name: this.icon(),
      className: "EventMessage-icon"
    }), m("div", {
      className: "EventMessage-info"
    }, describeEvent(message), " ", m("span", {
      className: "EventMessage-time"
    }, humanTime(message.createdAt()))));
  }
  icon() {
    switch (this.attrs.message.type()) {
      case 'userLeft':
        return 'fas fa-sign-out-alt';
      case 'renamed':
        return 'fas fa-pencil-alt';
      default:
        return 'fas fa-info-circle';
    }
  }
}
flarum.reg.add('flarum-messages', 'forum/components/EventMessage', EventMessage);